import{_ as p,a0 as o,w as d,s as u,I as s,x as l,a1 as a,A as e,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng | LCTT x X-CMD","titleTemplate":false,"description":"LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng","title":"LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng","tag":"201609","desc":""},"relativePath":"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng.md","filePath":"[post].md"}'),g={name:"201609/20160815 Alternative System Monitor Applet For LXDE  Xfce  And MATE - Multiload-ng.md"};function r(A,t,b,h,m,f){const i=o("Link");return d(),u("div",null,[t[21]||(t[21]=s("h1",{id:"lxde、xfce-及-mate-桌面環境下的又一系統監視器應用-multiload-ng",tabindex:"-1"},[l("LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng "),s("a",{class:"header-anchor",href:"#lxde、xfce-及-mate-桌面環境下的又一系統監視器應用-multiload-ng","aria-label":"Permalink to “LXDE、Xfce 及 MATE 桌面環境下的又一系統監視器應用：Multiload-ng”"},"​")],-1)),s("p",null,[a(i,{href:"https://github.com/udda/multiload-ng"},{default:e(()=>[...t[0]||(t[0]=[l("Multiload-ng",-1)])]),_:1}),t[1]||(t[1]=l(" 是一個 GTK2 圖形化系統監視器應用，可集成到 Xfce、LXDE 及 MATE 的桌面面板中， 它 fork 自原來的 GNOME Multiload 應用。它也可以運行在一個獨立的窗口中。",-1))]),t[22]||(t[22]=n('<p><img src="https://2.bp.blogspot.com/-U8CFzhSPJho/V7GigDbcLWI/AAAAAAAAYS0/pJMM6Rt5-HkbKljmxzP4-v0oGGxjvH8AgCLcB/s1600/multiload-ng-lxde.png" alt=""></p><p>Multiload-ng 的特點有：</p><ul><li>支持以下資源的圖形塊： CPU，內存，網絡，交換空間，平均負載，磁盤以及温度；</li><li>高度可定製；</li><li>支持配色方案；</li><li>自動適應容器（面板或窗口）的改變；</li><li>極低的 CPU 和內存佔用；</li><li>提供基本或詳細的提示信息；</li><li>可自定義雙擊觸發的動作。</li></ul><p>相比於原來的 Multiload 應用，Multiload-ng 含有一個額外的圖形塊（温度），以及更多獨立的圖形自定義選項，例如獨立的邊框顏色，支持配色方案，可根據自定義的動作對鼠標的點擊做出反應，圖形塊的方向可以被設定為與面板的方向無關。</p><p>它也可以運行在一個獨立的窗口中，而不需要面板：</p><p><img src="https://1.bp.blogspot.com/-hHoipwFlHrg/V7Gw2s107zI/AAAAAAAAYTQ/fS5OtiL7VvwDEzr6qO_gdEA_qB9YvJa5gCLcB/s400/multiload-ng-standalone.png" alt=""></p><p>另外，它的 GitHub page 上説還會帶來更多的圖形塊支持。</p><p>下圖展示的是在帶有一個垂直面板的 Xubuntu 16.04 中，該應用分別處於水平和垂直方向的效果：</p><p><img src="https://3.bp.blogspot.com/-xa0OML8T-lg/V7Gixksbt8I/AAAAAAAAYS4/Jxo-MukDh3sYlOOk9A1YGtARmte490g8ACLcB/s400/multiload-ng-xfce-horizontal.png" alt=""></p><p><img src="https://1.bp.blogspot.com/-WAD5MdDObD8/V7GixgVU0DI/AAAAAAAAYS8/uMhHJri1GJccRWvmf_tZkYeenVdxiENQwCLcB/s400/multiload-ng-xfce-vertical.png" alt=""></p><p>這個應用的偏好設置窗口雖然不是非常好看，但是有計劃去改進它：</p><p><img src="https://2.bp.blogspot.com/-P-ophDpc-gI/V7Gi_54b7JI/AAAAAAAAYTA/AHQck_JF_RcwZ1KbgHbaO2JRt24ZZdO3gCLcB/s320/multiload-ng-preferences.png" alt=""></p><p>Multiload-ng 當前使用的是 GTK2，所以它不能在構建自 GTK3 下的 Xfce 或 MATE 桌面環境（面板）下工作。</p><p>對於 Ubuntu 系統而言，只有 Ubuntu MATE 16.10 使用 GTK3。但是鑑於 MATE 的系統監視器應用也是 Multiload GNOME 的一個分支，所以它們大多數的功能相同（除了 Multiload-ng 提供的額外自定義選項和温度圖形塊）。</p>',14)),s("p",null,[t[3]||(t[3]=l("該應用的",-1)),a(i,{href:"https://github.com/udda/multiload-ng/wiki/Wishlist"},{default:e(()=>[...t[2]||(t[2]=[l("願望清單",-1)])]),_:1}),t[4]||(t[4]=l(" 中提及到了計劃支持 GTK3 的集成以及各種各樣的改進，例如温度塊資料的更多來源，能夠顯示十進制（KB、MB、GB……）或二進制（KiB、MiB、GiB……）單位等等。",-1))]),t[23]||(t[23]=n(`<h3 id="安裝-multiload-ng" tabindex="-1">安裝 Multiload-ng <a class="header-anchor" href="#安裝-multiload-ng" aria-label="Permalink to “安裝 Multiload-ng”">​</a></h3><p>請注意因為依賴的關係， Multiload-ng 不能在 Lubuntu 14.04 上構建。</p><p>Multiload-ng 可在 WebUpd8 的主 PPA （針對 Ubuntu 14.04 - 16.04 / Linux Mint 17.x 和 18）中獲取到。可以使用下面的命令來添加 PPA 並更新軟件源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:nilarimogard/webupd8</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><p>然後可以使用下面的命令來安裝這個應用：</p><ul><li>對於 LXDE (Lubuntu)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lxpanel-multiload-ng-plugin</span></span></code></pre></div><ul><li>對於 Xfce (Xubuntu，Linux Mint Xfce)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install xfce4-multiload-ng-plugin</span></span></code></pre></div><ul><li>對於 MATE (Ubuntu MATE，Linux Mint MATE)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mate-multiload-ng-applet</span></span></code></pre></div><ul><li>獨立安裝 (不需要集成到面板)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install multiload-ng-standalone</span></span></code></pre></div><p>一旦安裝完畢，便可以像其他應用那樣添加到桌面面板中了。需要注意的是在 LXDE 中，Multiload-ng 不能馬上出現在面板清單中，除非重新啓動面板。你可以通過重啓會話（登出後再登錄）或者使用下面的命令來重啓面板：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lxpanelctl restart</span></span></code></pre></div><p>獨立的 Multiload-ng 應用可以像其他正常應用那樣從菜單中啓動。</p>`,16)),s("p",null,[t[6]||(t[6]=l("如果要下載源碼或報告 bug 等，請看 Multiload-ng 的 ",-1)),a(i,{href:"https://github.com/udda/multiload-ng"},{default:e(()=>[...t[5]||(t[5]=[l("GitHub page",-1)])]),_:1}),t[7]||(t[7]=l("。",-1))]),t[24]||(t[24]=s("hr",null,null,-1)),s("p",null,[t[9]||(t[9]=l("via: ",-1)),a(i,{href:"http://www.webupd8.org/2016/08/alternative-system-monitor-applet-for.html"},{default:e(()=>[...t[8]||(t[8]=[l("http://www.webupd8.org/2016/08/alternative-system-monitor-applet-for.html",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=l("作者：",-1)),a(i,{href:"http://www.webupd8.org/p/about.html"},{default:e(()=>[...t[10]||(t[10]=[l("Andrew",-1)])]),_:1}),t[14]||(t[14]=l(" 譯者：",-1)),a(i,{href:"https://github.com/FSSlc"},{default:e(()=>[...t[11]||(t[11]=[l("FSSlc",-1)])]),_:1}),t[15]||(t[15]=l(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=l("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[16]||(t[16]=[l("LCTT",-1)])]),_:1}),t[19]||(t[19]=l(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...t[17]||(t[17]=[l("Linux中國",-1)])]),_:1}),t[20]||(t[20]=l(" 榮譽推出",-1))])])}const x=p(g,[["render",r]]);export{T as __pageData,x as default};
